 const equivalencies=[{source:'Bellevue College',code:'MATH& 151',target:'University of Washington Seattle',credit:'MATH 124 (5 quarter credits)',effective:'Summer 2008 onward in published guide',type:'Direct course credit · NSc [RSN]',checked:'2026-11-08',url:'https://admit.washington.edu/apply/transfer/equivalency-guide/bellevue/'},{source:'Bellevue College',code:'MATH& 152',target:'University of Washington Seattle',credit:'MATH 125 (5 quarter credits)',effective:'Summer 2008 onward in published guide',type:'Direct course credit · NSc',checked:'2026-11-08',url:'https://admit.washington.edu/apply/transfer/equivalency-guide/bellevue/'}];
 function recommend(answers){const scores={};answers.forEach(a=>{scores[a]=(scores[a]||0)+1});return majors.map((m,i)=>({...m,weight:m.tags.reduce((n,t)=>n+(scores[t]||0),0),i})).sort((a,b)=>b.weight-a.weight||a.i-b.i).slice(0,3);}
 function validate(courses,completed=[]){const errors=[];for(const c of courses){for(const pre of c.prereqs||[]){if(!completed.some(p=>norm(p)===norm(pre))&&!courses.some(p=>norm(p.code)===norm(pre)&&p.term<c.term))errors.push(`${c.code} needs ${pre} completed in an earlier term.`)}}return errors;}
 const norm=s=>String(s||'').toUpperCase().replace(/\s+/g,'');
 function excludedAttempt(c){const g=String(c.grade||'').trim().toUpperCase();return (c.imported&&/^(?:AUTUMN|WINTER|SPRING|SUMMER|FALL)\s+\d{4}$/i.test(c.code))||['failed','superseded','no-credit'].includes(c.attemptStatus)||c.repeatExcluded||/\/R\b/i.test(g+' '+(c.title||''))||['F','E','W','HW','AW','NW','NP','NC','NS','U'].includes(g)||(g!==''&&Number.isFinite(+g)&&+g===0)||(c.imported&&Number(c.credits)===0)}
 function passing(c){return !!c.completed&&!excludedAttempt(c)&&!['I','IP','N','X','RD'].includes(String(c.grade||'').trim().toUpperCase())}
 function generic(c){return /\dX{1,3}\b/i.test(c.code)}

 function matches(c,school,code){return c.institution?.trim().toLowerCase()===school.toLowerCase()&&norm(c.code)===norm(code)}
 function equivalence(a,b){if(!passing(a)||!passing(b))return null;for(const r of equivalencies){const targetCode=r.credit.split(' (')[0];const source=matches(a,r.source,r.code)?a:matches(b,r.source,r.code)?b:null;const target=matches(a,r.target,targetCode)?a:matches(b,r.target,targetCode)?b:null;if(source&&target&&source!==target&&Number(source.credits)===5&&Number(target.credits)===5){const year=String(source.term||'').match(/(?:19|20)\d{2}/);if(!year||+year[0]<2008||(+year[0]===2008&&!/summer|autumn|fall/i.test(source.term)))continue;return {...r,targetCode,keep:target};}}return null;}
 function consolidate(records){const active=[],merged=[],excluded=[];for(const raw of records){if(excludedAttempt(raw)){excluded.push({...raw,completed:false});continue}let incoming={...raw,creditOrigins:[...(raw.creditOrigins||[])]};const idx=active.findIndex(c=>{const same=c.institution?.trim().toLowerCase()===incoming.institution?.trim().toLowerCase()&&norm(c.code)===norm(incoming.code);return (same&&(!(generic(c)||generic(incoming))||(c.recordKey&&c.recordKey===incoming.recordKey)))||!!equivalence(c,incoming)});if(idx<0){active.push(incoming);continue}const old=active[idx],evidence=equivalence(old,incoming);const year=c=>+(String(c.term||'').match(/(?:19|20)\d{2}/)?.[0]||0);let keep=evidence?evidence.keep:(passing(incoming)&&!passing(old)?incoming:passing(old)&&!passing(incoming)?old:year(incoming)>=year(old)?incoming:old),other=keep===incoming?old:incoming;const origin=c=>({code:c.code,title:c.title,institution:c.institution,term:c.term||'',grade:c.grade||'',credits:c.credits});const origins=[...(keep.creditOrigins||[]),origin(other),...(other.creditOrigins||[])];const seen=new Set();active[idx]={...keep,creditOrigins:origins.filter(o=>{const k=JSON.stringify(o);if(seen.has(k))return false;seen.add(k);return true}),equivalenceEvidence:evidence?{url:evidence.url,checked:evidence.checked,sourceCode:evidence.code,targetCode:evidence.targetCode}:keep.equivalenceEvidence};merged.push({removed:origin(other),kept:origin(keep),verified:!!evidence});}return {courses:active,merged,excluded};}
 function completedCodes(records,target){const codes=new Set();for(const c of records.filter(passing)){codes.add(c.code);for(const o of c.creditOrigins||[])codes.add(o.code);for(const r of equivalencies){if(target===r.target&&matches(c,r.source,r.code)&&Number(c.credits)===5){const y=String(c.term||'').match(/(?:19|20)\d{2}/);if(y&&(+y[0]>2008||(+y[0]===2008&&/summer|autumn|fall/i.test(c.term))))codes.add(r.credit.split(' (')[0]);}}}return [...codes];}
 function schedule(courses,completed=[],limit=15){
  const complete=new Set(completed.map(norm));const pending=courses.filter(c=>!complete.has(norm(c.code)));const index=new Map(pending.map((c,i)=>[norm(c.code),i]));let blocked=new Set();
  pending.forEach((c,i)=>{if(c.credits>limit||c.credits<=0||(c.prereqs||[]).some(p=>!complete.has(norm(p))&&!index.has(norm(p))))blocked.add(i)});
  let changed=true;while(changed){changed=false;pending.forEach((c,i)=>{if(!blocked.has(i)&&(c.prereqs||[]).some(p=>blocked.has(index.get(norm(p))))){blocked.add(i);changed=true}})}
  const eligible=pending.filter((_,i)=>!blocked.has(i));let out=[],method='critical-path heuristic';
  // Breadth-first search over completed-course sets finds the minimum number of terms.
  if(eligible.length<=14){const n=eligible.length,full=(1<<n)-1,ids=new Map(eligible.map((c,i)=>[norm(c.code),i]));let frontier=[{mask:0,path:[]}],seen=new Set([0]),winner=null,work=0,aborted=false;
   while(frontier.length&&!winner&&!aborted){const next=[];for(const node of frontier){if(node.mask===full){winner=node;break}let ready=0;eligible.forEach((c,i)=>{if(!(node.mask&(1<<i))&&(c.prereqs||[]).every(p=>complete.has(norm(p))||(ids.has(norm(p))&&(node.mask&(1<<ids.get(norm(p)))))))ready|=1<<i});if(!ready)continue;
    for(let set=ready;set;set=(set-1)&ready){if(++work>150000){aborted=true;break}let credits=0;for(let i=0;i<n;i++)if(set&(1<<i))credits+=eligible[i].credits;if(credits>limit)continue;let maximal=true;for(let i=0;i<n;i++)if((ready&(1<<i))&&!(set&(1<<i))&&credits+eligible[i].credits<=limit){maximal=false;break}if(!maximal)continue;const mask=node.mask|set;if(seen.has(mask))continue;seen.add(mask);next.push({mask,path:[...node.path,set]});}
    if(aborted)break;}frontier=next;}
   if(winner){method='minimum terms for entered constraints';winner.path.forEach((set,term)=>eligible.forEach((c,i)=>{if(set&(1<<i))out.push({...c,term})}));}
  }
  if(!out.length&&eligible.length){const done=new Set(complete);let left=[...eligible],term=0;const depth=(c,visited=new Set())=>{if(visited.has(norm(c.code)))return 0;const v=new Set(visited).add(norm(c.code));return 1+Math.max(0,...eligible.filter(x=>(x.prereqs||[]).some(p=>norm(p)===norm(c.code))).map(x=>depth(x,v)))};while(left.length&&term<40){let credits=0;const ready=left.filter(c=>(c.prereqs||[]).every(p=>done.has(norm(p)))).sort((a,b)=>depth(b)-depth(a)||b.credits-a.credits),selected=[];for(const c of ready)if(credits+c.credits<=limit){selected.push(c);credits+=c.credits}if(!selected.length)break;out.push(...selected.map(c=>({...c,term})));selected.forEach(c=>done.add(norm(c.code)));left=left.filter(c=>!selected.includes(c));term++;}}
  const planned=new Set(out.map(c=>norm(c.code)));return {courses:out,blocked:pending.filter(c=>!planned.has(norm(c.code))).map(c=>c.code),method};
 }

 return {majors,universities,equivalencies,recommend,validate,schedule,consolidate,completedCodes,passing,excludedAttempt};
